-- nvim's colors. Generated by theme/retheme for {{theme.host}} ({{theme.palette}}, {{theme.variation}}):
-- edit theme/ and run retheme, not this file.
--
-- `theme` fills every color role kanagawa.nvim draws with (ui, syn, diag, vcs, diff, term) from
-- this machine's tokens: code from the variation's [syntax], the editor from [ui], the terminal
-- from [ansi]. So nvim is on the variation like everything else, and its code matches bat and
-- delta. `palette` refills kanagawa.nvim's raw Wave colors from the palette's slots, for the few
-- highlights that name a raw color rather than a role.
return {
    light = {{theme.light}},
    -- Roles kanagawa.nvim has no slot for; init.lua's overrides apply them.
    code = { storage = "{{storage}}" },
    theme = {
        ui = {
            fg = "{{text}}", fg_dim = "{{textAlt}}", fg_reverse = "{{selectionDeep}}",
            bg_dim = "{{bg1}}", bg_gutter = "{{layer}}",
            bg_m3 = "{{surface}}", bg_m2 = "{{bg1}}", bg_m1 = "{{bg2}}",
            bg = "{{content}}", bg_p1 = "{{layer}}", bg_p2 = "{{layerHover}}",
            special = "{{violet_muted}}", nontext = "{{line}}", whitespace = "{{line}}",
            bg_search = "{{selection}}", bg_visual = "{{selectionDeep}}",
            pmenu = { fg = "{{text}}", fg_sel = "none", bg = "{{selectionDeep}}", bg_sel = "{{selection}}",
                      bg_sbar = "{{selectionDeep}}", bg_thumb = "{{selection}}" },
            float = { fg = "{{textAlt}}", bg = "{{surface}}", fg_border = "{{line}}", bg_border = "{{surface}}" },
        },
        syn = {
            string = "{{strings}}", variable = "none", number = "{{numbers}}", constant = "{{constants}}",
            identifier = "{{identifiers}}", parameter = "{{parameters}}", fun = "{{functions}}",
            statement = "{{keywords}}", keyword = "{{keywords}}", operator = "{{operators}}",
            preproc = "{{preproc}}", type = "{{types}}", regex = "{{regexps}}", deprecated = "{{deprecated}}",
            comment = "{{comments}}", punct = "{{punctuation}}",
            special1 = "{{specials}}", special2 = "{{builtins}}", special3 = "{{controlFlow}}",
        },
        diag = { ok = "{{success}}", error = "{{errors}}", warning = "{{warning}}",
                 info = "{{diagnosticInfo}}", hint = "{{diagnosticHint}}" },
        vcs = { added = "{{gitAdded}}", removed = "{{gitRemoved}}", changed = "{{gitChanged}}" },
        diff = { add = "{{diffAdd}}", delete = "{{diffDelete}}", change = "{{diffChangeLine}}", text = "{{diffChange}}" },
        term = {
            "{{ansiBlack}}", "{{ansiRed}}", "{{ansiGreen}}", "{{ansiYellow}}",
            "{{ansiBlue}}", "{{ansiMagenta}}", "{{ansiCyan}}", "{{ansiWhite}}",
            "{{ansiBrightBlack}}", "{{ansiBrightRed}}", "{{ansiBrightGreen}}", "{{ansiBrightYellow}}",
            "{{ansiBrightBlue}}", "{{ansiBrightMagenta}}", "{{ansiBrightCyan}}", "{{ansiBrightWhite}}",
            "{{ansi16}}", "{{ansi17}}",
        },
    },
    palette = {
        sumiInk0      = "{{bg0}}",
        sumiInk1      = "{{bg1}}",
        sumiInk2      = "{{bg2}}",
        sumiInk3      = "{{bg3}}",
        sumiInk4      = "{{bg4}}",
        sumiInk5      = "{{bg5}}",
        sumiInk6      = "{{bg6}}",
        waveBlue1     = "{{bg_blue}}",
        waveBlue2     = "{{bg_blue_bright}}",
        winterBlue    = "{{bg_blue_dim}}",
        winterGreen   = "{{bg_green}}",
        winterRed     = "{{bg_red}}",
        winterYellow  = "{{bg_yellow}}",
        fujiWhite     = "{{fg}}",
        oldWhite      = "{{fg_dim}}",
        fujiGray      = "{{fg_faint}}",
        katanaGray    = "{{gray}}",
        waveRed       = "{{red}}",
        peachRed      = "{{red_bright}}",
        samuraiRed    = "{{red_strong}}",
        autumnRed     = "{{red_deep}}",
        surimiOrange  = "{{orange}}",
        roninYellow   = "{{orange_strong}}",
        carpYellow    = "{{yellow}}",
        autumnYellow  = "{{yellow_deep}}",
        boatYellow2   = "{{yellow_muted}}",
        boatYellow1   = "{{yellow_dim}}",
        springGreen   = "{{green}}",
        autumnGreen   = "{{green_deep}}",
        waveAqua2     = "{{aqua}}",
        waveAqua1     = "{{aqua_deep}}",
        crystalBlue   = "{{blue}}",
        springBlue    = "{{blue_bright}}",
        lightBlue     = "{{blue_light}}",
        dragonBlue    = "{{blue_muted}}",
        oniViolet     = "{{violet}}",
        oniViolet2    = "{{violet_light}}",
        springViolet1 = "{{violet_muted}}",
        springViolet2 = "{{lavender}}",
        sakuraPink    = "{{pink}}",
    },
}
